-- ============================================================
-- 20261015000001 - CORE: helpers + tables
-- ============================================================
-- Design rules (why inserts no longer fail):
--   * Every NOT NULL column that the app does not send has either a
--     DEFAULT or is filled by a BEFORE INSERT trigger (see ..0002).
--   * IDs are "generated BY DEFAULT" so imports / restores that carry
--     their own ids work (call public.fix_sequences() afterwards).
--   * No extensions are required (no citext / pg_trgm / pgcrypto), so
--     nothing can fail on a project that restricts extensions.
--   * Money is numeric(12,2) everywhere.
--   * Foreign keys use RESTRICT for business records and SET NULL for
--     "who did it" columns, so removing a login never breaks history.
-- ============================================================

-- Business timezone. Supabase runs in UTC; the business is in Asia/Karachi.
create or replace function public.today_pk()
returns date language sql stable
as $$ select (now() at time zone 'Asia/Karachi')::date $$;

-- ------------------------------------------------------------
-- PROFILES - application logins, 1:1 with auth.users
-- ------------------------------------------------------------
create table public.profiles (
  id          uuid primary key references auth.users(id) on delete cascade,
  full_name   text not null check (btrim(full_name) <> ''),
  role        text not null default 'staff' check (role in ('admin','staff')),
  is_active   boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- ------------------------------------------------------------
-- AREAS - villages / zones served
-- ------------------------------------------------------------
create table public.areas (
  id          bigint generated by default as identity primary key,
  name        text not null check (btrim(name) <> ''),
  description text,
  created_at  timestamptz not null default now()
);
create unique index areas_name_uniq on public.areas (lower(btrim(name)));

-- ------------------------------------------------------------
-- PACKAGES - billing tiers
-- ------------------------------------------------------------
create table public.packages (
  id           bigint generated by default as identity primary key,
  name         text not null check (btrim(name) <> ''),
  speed_label  text,
  monthly_fee  numeric(12,2) not null check (monthly_fee >= 0),
  description  text,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create unique index packages_name_uniq on public.packages (lower(btrim(name)));

-- ------------------------------------------------------------
-- EMPLOYEES - HR record; optionally linked to a login (profile_id)
-- ------------------------------------------------------------
create table public.employees (
  id              bigint generated by default as identity primary key,
  profile_id      uuid unique references public.profiles(id) on delete set null,
  full_name       text not null check (btrim(full_name) <> ''),
  phone           text,
  role_title      text,
  area_id         bigint references public.areas(id) on delete set null,
  monthly_salary  numeric(12,2) check (monthly_salary is null or monthly_salary >= 0),
  is_active       boolean not null default true,
  joined_at       date not null default public.today_pk(),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index employees_area_idx   on public.employees (area_id);
create index employees_active_idx on public.employees (is_active);

-- ------------------------------------------------------------
-- CUSTOMERS
--   customer_code : filled by trigger (CUS-00001...) if not supplied
--   opening_balance: dues carried over from the paper register.
--                    May be NEGATIVE (customer paid in advance).
--   balance       : DERIVED, maintained by triggers - never edit by hand
--   join_date     : first month the customer can be billed
-- ------------------------------------------------------------
create table public.customers (
  id               bigint generated by default as identity primary key,
  customer_code    text not null unique,
  username         text not null check (btrim(username) <> ''),
  phone            text not null,
  package_id       bigint not null references public.packages(id) on delete restrict,
  area_id          bigint not null references public.areas(id)    on delete restrict,
  seller_id        bigint references public.employees(id) on delete set null,
  address          text,
  opening_balance  numeric(12,2) not null default 0,
  balance          numeric(12,2) not null default 0,
  service_status   text not null default 'on'     check (service_status  in ('on','off')),
  customer_status  text not null default 'active' check (customer_status in ('active','inactive')),
  cnic             text,
  father_name      text,
  notes            text,
  join_date        date not null default public.today_pk(),
  created_by       uuid references public.profiles(id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index customers_area_idx     on public.customers (area_id);
create index customers_package_idx  on public.customers (package_id);
create index customers_seller_idx   on public.customers (seller_id);
create index customers_status_idx   on public.customers (customer_status);
create index customers_phone_idx    on public.customers (phone);
create index customers_username_idx on public.customers (lower(username));

-- ------------------------------------------------------------
-- MONTHLY_FEES - one fee per customer per month
--   billing_month : any date in the month is accepted; the trigger
--                   normalises it to the 1st
--   due_date      : defaults to the 10th of the month
--   amount_due    : defaults to the package fee; it is a SNAPSHOT
-- ------------------------------------------------------------
create table public.monthly_fees (
  id             bigint generated by default as identity primary key,
  customer_id    bigint not null references public.customers(id) on delete restrict,
  billing_month  date not null,
  amount_due     numeric(12,2) not null check (amount_due >= 0),
  due_date       date not null,
  package_id     bigint references public.packages(id) on delete set null,
  created_by     uuid references public.profiles(id) on delete set null,
  created_at     timestamptz not null default now(),
  constraint monthly_fees_customer_month_uniq unique (customer_id, billing_month),
  constraint monthly_fees_id_customer_uniq    unique (id, customer_id),
  constraint monthly_fees_first_of_month check (billing_month = date_trunc('month', billing_month::timestamp)::date)
);
create index monthly_fees_month_idx on public.monthly_fees (billing_month);
create index monthly_fees_due_idx   on public.monthly_fees (due_date);

-- ------------------------------------------------------------
-- PAYMENTS - never deleted; corrected by reversal
--   customer_id    : filled from the fee; the composite FK guarantees a
--                    payment can never point at another customer's fee
--   receipt_number : generated by trigger (RCP-YYYY-NNNNNN)
--   received_by    : stamped from the logged-in user (null for SQL imports)
-- ------------------------------------------------------------
create table public.payments (
  id                bigint generated by default as identity primary key,
  customer_id       bigint not null references public.customers(id) on delete restrict,
  monthly_fee_id    bigint not null,
  amount_paid       numeric(12,2) not null check (amount_paid > 0),
  payment_method    text not null default 'cash' check (payment_method in ('cash','bank_transfer','other')),
  payment_date      date not null default public.today_pk(),
  received_by       uuid references public.profiles(id) on delete set null,
  receipt_number    text not null unique,
  notes             text,
  reversed_at       timestamptz,
  reversed_by       uuid references public.profiles(id) on delete set null,
  reversal_reason   text,
  whatsapp_sent     boolean not null default false,
  whatsapp_sent_at  timestamptz,
  created_at        timestamptz not null default now(),
  constraint payments_fee_customer_fk
    foreign key (monthly_fee_id, customer_id) references public.monthly_fees (id, customer_id) on delete restrict,
  constraint payments_reversal_consistent
    check (reversed_at is not null or (reversed_by is null and reversal_reason is null))
);
create index payments_customer_idx    on public.payments (customer_id);
create index payments_fee_idx         on public.payments (monthly_fee_id);
create index payments_date_idx        on public.payments (payment_date);
create index payments_received_by_idx on public.payments (received_by);

-- ------------------------------------------------------------
-- COMPLAINTS
-- ------------------------------------------------------------
create table public.complaints (
  id                bigint generated by default as identity primary key,
  customer_id       bigint not null references public.customers(id) on delete restrict,
  complaint_text    text not null check (btrim(complaint_text) <> ''),
  category          text not null default 'other'
                      check (category in ('slow_speed','no_connection','billing','hardware','other')),
  status            text not null default 'open'
                      check (status in ('open','in_progress','resolved','closed')),
  assigned_to       uuid references public.profiles(id) on delete set null,
  resolution_notes  text,
  created_by        uuid references public.profiles(id) on delete set null,
  created_at        timestamptz not null default now(),
  resolved_at       timestamptz
);
create index complaints_customer_idx   on public.complaints (customer_id);
create index complaints_status_idx     on public.complaints (status);
create index complaints_assigned_idx   on public.complaints (assigned_to);
create index complaints_created_by_idx on public.complaints (created_by);

-- ------------------------------------------------------------
-- ACCOUNTS (cash box / bank) and their transactions
--   current_balance moves only through account_transactions (trigger)
-- ------------------------------------------------------------
create table public.accounts (
  id               bigint generated by default as identity primary key,
  name             text not null check (btrim(name) <> ''),
  account_type     text not null default 'cash' check (account_type in ('cash','bank')),
  current_balance  numeric(14,2) not null default 0,
  is_active        boolean not null default true,
  created_at       timestamptz not null default now()
);
create unique index accounts_name_uniq on public.accounts (lower(btrim(name)));

create table public.account_transactions (
  id                    bigint generated by default as identity primary key,
  account_id            bigint not null references public.accounts(id) on delete restrict,
  transaction_type      text not null check (transaction_type in ('credit','debit')),
  amount                numeric(12,2) not null check (amount > 0),
  description           text,
  reference_payment_id  bigint references public.payments(id) on delete set null,
  created_by            uuid references public.profiles(id) on delete set null,
  created_at            timestamptz not null default now()
);
create index account_tx_account_idx on public.account_transactions (account_id);
create index account_tx_payment_idx on public.account_transactions (reference_payment_id);

-- ------------------------------------------------------------
-- JOURNAL_ENTRIES - daily cash book
-- ------------------------------------------------------------
create table public.journal_entries (
  id                    bigint generated by default as identity primary key,
  entry_date            date not null default public.today_pk(),
  entry_type            text not null check (entry_type in ('income','expense')),
  category              text not null default 'General' check (btrim(category) <> ''),
  amount                numeric(12,2) not null check (amount > 0),
  description           text,
  reference_payment_id  bigint references public.payments(id) on delete set null,
  created_by            uuid references public.profiles(id) on delete set null,
  created_at            timestamptz not null default now()
);
create index journal_entries_date_idx on public.journal_entries (entry_date);
create index journal_ref_payment_idx  on public.journal_entries (reference_payment_id);

-- ------------------------------------------------------------
-- SMS / WhatsApp templates and log
-- ------------------------------------------------------------
create table public.sms_templates (
  id             bigint generated by default as identity primary key,
  name           text not null check (btrim(name) <> ''),
  template_text  text not null check (btrim(template_text) <> ''),
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create unique index sms_templates_name_uniq on public.sms_templates (lower(btrim(name)));

create table public.sms_logs (
  id                  bigint generated by default as identity primary key,
  customer_id         bigint references public.customers(id) on delete set null,
  phone               text not null,
  message_text        text not null,
  status              text not null default 'pending' check (status in ('pending','sent','failed')),
  provider            text not null default 'whatsapp_manual',
  error_message       text,
  sent_by             uuid references public.profiles(id) on delete set null,
  related_payment_id  bigint references public.payments(id) on delete set null,
  created_at          timestamptz not null default now(),
  sent_at             timestamptz
);
create index sms_logs_customer_idx on public.sms_logs (customer_id);
create index sms_logs_status_idx   on public.sms_logs (status);
create index sms_logs_payment_idx  on public.sms_logs (related_payment_id);
create index sms_logs_created_idx  on public.sms_logs (created_at desc);
create index sms_logs_sent_by_idx  on public.sms_logs (sent_by);

-- ------------------------------------------------------------
-- COMPANY_LOGS - audit trail, written by triggers only
-- ------------------------------------------------------------
create table public.company_logs (
  id           bigint generated by default as identity primary key,
  actor_id     uuid references public.profiles(id) on delete set null,
  action       text not null,
  entity_type  text not null,
  entity_id    text,
  details      jsonb,
  created_at   timestamptz not null default now()
);
create index company_logs_actor_idx   on public.company_logs (actor_id);
create index company_logs_created_idx on public.company_logs (created_at desc);
create index company_logs_entity_idx  on public.company_logs (entity_type, entity_id);

-- ============================================================
-- Helper functions (need the tables above)
-- ============================================================

-- Active admin?
create or replace function public.is_admin()
returns boolean language sql security definer stable set search_path = public, auth
as $$ select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin' and is_active) $$;

-- Any active login?
create or replace function public.is_active_user()
returns boolean language sql security definer stable set search_path = public, auth
as $$ select exists (select 1 from public.profiles where id = auth.uid() and is_active) $$;

-- SQL editor / migrations / service role (not a browser session).
create or replace function public.is_trusted_session()
returns boolean language sql stable
as $$ select current_user in ('postgres', 'supabase_admin', 'service_role') $$;

-- Same idea, but for SECURITY DEFINER functions, where current_user is always the
-- function owner. Looks at the original caller instead: no JWT (SQL editor) or the
-- service role is trusted; 'authenticated' / 'anon' browser sessions never are.
create or replace function public.is_trusted_caller()
returns boolean language sql stable
as $$ select coalesce(auth.role(), '') not in ('authenticated', 'anon') $$;

-- True while a bulk import / restore is running:
--   begin; select set_config('app.bulk_load', 'on', true); ...inserts...; commit;
-- It switches OFF the automatic side-effects (journal, account postings,
-- audit rows, auto-created fees) so historical data can be loaded as-is.
create or replace function public.is_bulk_load()
returns boolean language sql stable
as $$ select coalesce(current_setting('app.bulk_load', true), '') = 'on' $$;

create or replace function public.company_name()
returns text language sql immutable
as $$ select 'Rana Cable Internet'::text $$;

-- Phone normaliser. Pakistani mobiles become 03XXXXXXXXX; any other number
-- (landline, foreign) is kept as digits instead of being rejected.
-- Returns NULL only when there are fewer than 7 or more than 15 digits.
create or replace function public.normalize_phone(p text)
returns text language plpgsql immutable
as $$
declare d text := regexp_replace(coalesce(p, ''), '\D', '', 'g');
begin
  if d like '0092%' then d := substr(d, 5);
  elsif d like '92%' and length(d) = 12 then d := substr(d, 3);
  end if;
  if length(d) = 10 and d like '3%' then d := '0' || d; end if;
  if d ~ '^03[0-9]{9}$' then return d; end if;
  if length(d) between 7 and 15 then return d; end if;
  return null;
end $$;
